CREATE TABLE COMPANY (COMPANY_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, COMPANY_NAME VARCHAR2(200) NOT NULL, SYMBOL VARCHAR2(50) UNIQUE, INDUSTRY VARCHAR2(150), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);

CREATE TABLE FINANCIAL_PERIOD (PERIOD_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, COMPANY_ID NUMBER NOT NULL, FISCAL_YEAR VARCHAR2(20) NOT NULL, PERIOD_START DATE, PERIOD_END DATE, STATEMENT_SCOPE VARCHAR2(20) NOT NULL, CURRENCY_CODE VARCHAR2(10), UNIT_LABEL VARCHAR2(30), CONSTRAINT FK_FP_COMPANY FOREIGN KEY (COMPANY_ID) REFERENCES COMPANY(COMPANY_ID), CONSTRAINT UQ_FP UNIQUE (COMPANY_ID, FISCAL_YEAR, STATEMENT_SCOPE));

CREATE TABLE FINANCIAL_ITEM (ITEM_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STANDARD_ITEM_CODE VARCHAR2(50) NOT NULL UNIQUE, STANDARD_ITEM_NAME VARCHAR2(200) NOT NULL, CATEGORY VARCHAR2(50) NOT NULL, FORMULA_NOTES VARCHAR2(1000));

CREATE TABLE RAW_FINANCIAL_DATA (RAW_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, COMPANY_ID NUMBER NOT NULL, FINANCIAL_YEAR VARCHAR2(20) NOT NULL, RAW_ITEM_NAME VARCHAR2(500) NOT NULL, RAW_VALUE NUMBER, CURRENCY_CODE VARCHAR2(10), UNIT_LABEL VARCHAR2(30), STATEMENT_TYPE VARCHAR2(50), STATEMENT_SCOPE VARCHAR2(20), SOURCE_DOCUMENT VARCHAR2(500), SOURCE_PAGE NUMBER, EXTRACTION_CONFIDENCE NUMBER(5,4), VALIDATED_FLAG CHAR(1) DEFAULT 'N' NOT NULL, CONSTRAINT FK_RFD_COMPANY FOREIGN KEY (COMPANY_ID) REFERENCES COMPANY(COMPANY_ID), CONSTRAINT CK_RFD_VALIDATED CHECK (VALIDATED_FLAG IN ('Y','N')));

CREATE TABLE ITEM_MAPPING (MAPPING_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, RAW_ITEM_NAME VARCHAR2(500) NOT NULL, ITEM_ID NUMBER NOT NULL, MAPPING_CONFIDENCE NUMBER(5,4), CONSTRAINT FK_IM_ITEM FOREIGN KEY (ITEM_ID) REFERENCES FINANCIAL_ITEM(ITEM_ID), CONSTRAINT UQ_IM UNIQUE (RAW_ITEM_NAME, ITEM_ID));

CREATE TABLE FINANCIAL_VALUE (VALUE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, PERIOD_ID NUMBER NOT NULL, ITEM_ID NUMBER NOT NULL, VALUE_NUMBER NUMBER NOT NULL, SOURCE_RAW_ID NUMBER, CONSTRAINT FK_FV_PERIOD FOREIGN KEY (PERIOD_ID) REFERENCES FINANCIAL_PERIOD(PERIOD_ID), CONSTRAINT FK_FV_ITEM FOREIGN KEY (ITEM_ID) REFERENCES FINANCIAL_ITEM(ITEM_ID), CONSTRAINT FK_FV_RAW FOREIGN KEY (SOURCE_RAW_ID) REFERENCES RAW_FINANCIAL_DATA(RAW_ID), CONSTRAINT UQ_FV UNIQUE (PERIOD_ID, ITEM_ID));

CREATE TABLE FINANCIAL_RATIO (RATIO_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, PERIOD_ID NUMBER NOT NULL, RATIO_CODE VARCHAR2(50) NOT NULL, RATIO_VALUE NUMBER, CALCULATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_FR_PERIOD FOREIGN KEY (PERIOD_ID) REFERENCES FINANCIAL_PERIOD(PERIOD_ID));

CREATE TABLE RISK_ANALYSIS (RISK_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, PERIOD_ID NUMBER NOT NULL, LIQUIDITY_RISK_SCORE NUMBER, PROFITABILITY_RISK_SCORE NUMBER, OVERALL_RISK_LEVEL VARCHAR2(30), ANALYSIS_TEXT CLOB, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_RA_PERIOD FOREIGN KEY (PERIOD_ID) REFERENCES FINANCIAL_PERIOD(PERIOD_ID));

CREATE TABLE ANOMALY (ANOMALY_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, PERIOD_ID NUMBER NOT NULL, METRIC_CODE VARCHAR2(50) NOT NULL, OBSERVED_VALUE NUMBER, ANOMALY_SCORE NUMBER, ANOMALY_STATUS VARCHAR2(30), MODEL_VERSION VARCHAR2(100), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_AN_PERIOD FOREIGN KEY (PERIOD_ID) REFERENCES FINANCIAL_PERIOD(PERIOD_ID));

CREATE TABLE DOCUMENT (DOCUMENT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, COMPANY_ID NUMBER NOT NULL, DOCUMENT_NAME VARCHAR2(500) NOT NULL, DOCUMENT_YEAR VARCHAR2(20), FILE_PATH VARCHAR2(1000), SOURCE_URL VARCHAR2(1000), CONSTRAINT FK_DOC_COMPANY FOREIGN KEY (COMPANY_ID) REFERENCES COMPANY(COMPANY_ID));

CREATE TABLE RAG_EVIDENCE (EVIDENCE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, DOCUMENT_ID NUMBER NOT NULL, CHUNK_TEXT CLOB NOT NULL, SOURCE_PAGE NUMBER, CHUNK_INDEX NUMBER, RETRIEVAL_SCORE NUMBER, CONSTRAINT FK_RE_DOC FOREIGN KEY (DOCUMENT_ID) REFERENCES DOCUMENT(DOCUMENT_ID));

CREATE TABLE AUDIT_LOG (AUDIT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, TABLE_NAME VARCHAR2(128) NOT NULL, OPERATION VARCHAR2(20) NOT NULL, RECORD_ID VARCHAR2(100), CHANGED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CHANGED_BY VARCHAR2(128) DEFAULT USER NOT NULL, OLD_DATA CLOB, NEW_DATA CLOB);
